const reddet = (bag: Baglanti, code: HataKodu, neden: string, ek: GunlukAlanlari = {}): void => {
  gunluk.uyari(MODUL, "el_sikisma_ret", { code, neden, ...ek });
  yaz(bag, { v: PROTOKOL_SURUMU, type: "kopru_ret", code });
  baglantiKapat(bag);

